import {test,expect} from 'playwright/test';
import {mkdir,writeFile} from 'node:fs/promises';
import {prepare,ready} from './fixtures/browser.js';

// These coordinates are immutable measurements of the approved collage, not
// screenshots generated by the application. Pixel error is reported honestly;
// functional content, browser text rasterization and live map data also differ.
const manifest=JSON.parse(await (await import('node:fs/promises')).readFile(new URL('../assets/visual-kit/manifest.json',import.meta.url),'utf8'));
const panes=[['login','login_mockup_reference.png','light'],['painel','dashboard_mockup_reference.png','light'],['clientes','clients_mockup_reference.png','dark'],['mapa','routes_mockup_reference.png','dark'],['dados','spreadsheets_mockup_reference.png','dark']].map(([id,file,theme])=>{const [x,y,right,bottom]=manifest.assets.mockup_crops[file];return{id,file,x,y,w:right-x,h:bottom-y,theme};});
for(const pane of panes)test(`approved reference: ${pane.id}`,async({page,context})=>{
  const viewport={width:pane.w*2,height:pane.h*2};await page.setViewportSize(viewport);
  await prepare(page,{authenticated:pane.id!=='login',theme:pane.theme,liveMaps:pane.id==='mapa'});await ready(page);
  if(pane.id!=='login')await page.locator(`.tabs [data-tab="${pane.id}"]`).click();
  if(pane.id==='dados'){await page.locator('#cloudCheck').click();await expect(page.locator('#cloudStatus')).not.toHaveText('Aguardando verificação.');}
  if(pane.id==='mapa'){
    await expect(page.locator('#map canvas')).toBeVisible({timeout:20000});
    await expect.poll(()=>page.evaluate(()=>map?.isStyleLoaded()&&map?.areTilesLoaded()),{timeout:35000}).toBe(true);
    await expect.poll(()=>page.evaluate(()=>{const l=map.getStyle().layers.find(l=>l.type==='background');return map.getPaintProperty(l.id,'background-color');})).toBe('#062432');
  }
  await page.evaluate(()=>document.fonts.ready);
  const geometry=await page.evaluate(()=>{
    const bounds=sel=>{const r=document.querySelector(sel).getBoundingClientRect();return{x:r.x,y:r.y,w:r.width,h:r.height};};
    return{header:bounds('body>header'),sidebar:bounds('.tabs'),login:bounds('.auth-panel'),hero:bounds('.traxio-hero')};
  });
  if(pane.id==='login'){
    const previous=!!process.env.TRAXIO_REVIEW_ORIGIN;
    const left=previous?296*viewport.width/563:355*2;
    const top=previous?(viewport.height-526*viewport.width/563)/2+59*viewport.width/563:71*2;
    const width=previous?249*viewport.width/563:300*2;
    expect(Math.abs(geometry.login.x-left)).toBeLessThan(3);
    expect(Math.abs(geometry.login.y-top)).toBeLessThan(3);
    expect(Math.abs(geometry.login.w-width)).toBeLessThan(3);
  }else{
    const previous=!!process.env.TRAXIO_REVIEW_ORIGIN;
    const header=previous?72:({painel:71,mapa:69,dados:69}[pane.id]||72),sidebar=previous?(pane.id==='painel'?160:164):({painel:157,mapa:158,dados:154}[pane.id]||164);
    expect(Math.abs(geometry.header.h-header*viewport.height/650)).toBeLessThan(3);
    expect(Math.abs(geometry.sidebar.w-sidebar*viewport.height/650)).toBeLessThan(3);
  }
  const output=process.env.TRAXIO_REFERENCE_OUTPUT||'docs/captures/reference';
  await mkdir(output,{recursive:true});
  const actual=await page.screenshot({path:`${output}/${pane.id}-actual.png`,animations:'disabled'});
  const review=await context.newPage();await review.setViewportSize({width:viewport.width*2,height:viewport.height});await review.goto('http://127.0.0.1:4173/assets/visual-kit/reference/1411.png');
  const metrics=await review.evaluate(async({pane,actual})=>{
    const load=src=>new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=src;});
    const [ref,img]=await Promise.all([load('/assets/visual-kit/assets/'+pane.file),load('data:image/png;base64,'+actual)]);
    const approved=document.createElement('canvas');approved.width=img.width;approved.height=img.height;
    const ac=approved.getContext('2d');ac.drawImage(ref,0,0,ref.width,ref.height,0,0,img.width,img.height);
    const current=document.createElement('canvas');current.width=img.width;current.height=img.height;const cc=current.getContext('2d');cc.drawImage(img,0,0);
    const a=ac.getImageData(0,0,img.width,img.height).data,b=cc.getImageData(0,0,img.width,img.height).data;
    let absolute=0,mismatch=0;for(let i=0;i<a.length;i+=4){let d=0;for(let c=0;c<3;c++)d+=Math.abs(a[i+c]-b[i+c]);absolute+=d;if(d/3>24)mismatch++;}
    const thumbnail=document.createElement('canvas');thumbnail.width=pane.w;thumbnail.height=pane.h;thumbnail.getContext('2d').drawImage(img,0,0,pane.w,pane.h);
    const preview=thumbnail.toDataURL('image/png');
    document.documentElement.innerHTML='<head><title>Approved / actual</title><style>*{box-sizing:border-box}html,body{margin:0;background:#001e2d;overflow:hidden}body{display:flex}canvas,img{display:block}</style></head><body></body>';
    document.body.append(approved,img);
    return{preview,meanAbsoluteRGBError:absolute/(img.width*img.height*3),pixelsDifferingOver24:mismatch/(img.width*img.height),identical:absolute===0};
  },{pane,actual:actual.toString('base64')});
  const {preview,...pixelMetrics}=metrics;
  await writeFile(`${output}/${pane.id}-actual-preview.png`,Buffer.from(preview.split(',')[1],'base64'));
  await review.screenshot({path:`${output}/${pane.id}-comparison.png`});
  await writeFile(`${output}/${pane.id}-metrics.json`,JSON.stringify({reference:pane,viewport,geometry,metrics:pixelMetrics},null,2));await review.close();
});
